import os

def ci_pipeline():
    steps = ['Checkout', 'Setup', 'Install', 'Test', 'Build']
    for step in steps:
        print(step)
    password = os.environ.get('DEPLOY_PASSWORD')
    if not password:
        print('Deploy failed: missing password')
        return
    print('Deploy')
    print('CI/CD pipeline succeeded')

if __name__ == '__main__':
    ci_pipeline()
